(()=>{const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));const badge=(x,t='')=>`<span class="badge ${t}">${esc(x)}</span>`;const chips=a=>a?.length?`<div class="chips">${a.map((x,i)=>`<span class="chip ${i===0?'active':''}">${esc(x)}</span>`).join('')}</div>`:'';const fields=a=>a?.length?a.map(x=>`<div class="field"><label>${esc(x[0])}</label><div class="input ${x[1]?'':'placeholder'}">${esc(x[1]||x[2]||'')}</div></div>`).join(''):'';const rows=a=>a?.length?`<div class="row-list">${a.map(x=>`<div class="row"><div class="row-main"><div class="row-title">${esc(x[0])}</div>${x[1]?`<div class="row-meta">${esc(x[1])}</div>`:''}</div>${x[2]?`<div class="row-value">${esc(x[2])}</div>`:''}</div>`).join('')}</div>`:'';const stats=a=>a?.length?`<div class="stats">${a.map(x=>`<div class="stat"><b>${esc(x[1])}</b><span>${esc(x[0])}</span></div>`).join('')}</div>`:'';const cards=a=>a?.length?a.map(x=>`<div class="event-card"><div class="event-thumb"></div><div class="event-info"><div class="event-kicker">${esc(x[1]||'TODAY · 18:30')}</div><div class="event-title">${esc(x[0])}</div><div class="event-meta">${esc(x[2]||'Helsinki · 1.2 km · English / Finnish')}</div><div class="event-foot"><div class="facepile"><span class="avatar">A</span><span class="avatar">M</span><span class="avatar">J</span><span class="mini">${esc(x[3]||'6 going')}</span></div>${x[4]?`<span class="btn compact">${esc(x[4])}</span>`:''}</div></div></div>`).join(''):'';const actions=s=>{let a=[];if(s.primary)a.push(`<span class="btn">${esc(s.primary)}</span>`);if(s.secondary)a.push(`<span class="btn secondary">${esc(s.secondary)}</span>`);return a.length?`<div class="actions ${a.length>1?'two':''}">${a.join('')}</div>`:''};const messages=a=>a?.length?`<div class="message-list">${a.map((x,i)=>`<div class="message ${x[2]?'me':''}">${esc(x[0])}<span class="time">${esc(x[1]||'18:42')}</span></div>`).join('')}</div><div class="composer"><div class="input placeholder">Message</div><span class="btn compact">Send</span></div>`:'';function mapVisual(){return `<div class="mapbox"><div class="pin" style="left:22%;top:25%"><span>3</span></div><div class="pin" style="left:58%;top:39%"><span>8</span></div><div class="pin" style="left:74%;top:17%;background:#0F766E"><span>2</span></div><div class="map-card"><div class="event-kicker">TODAY · 19:00 · 900 m</div><div class="event-title">Board games at Oodi</div><div class="event-meta">Central Library · 4 places left</div><div class="actions two"><span class="btn">I'm going</span><span class="btn secondary">Details</span></div></div></div>`}function nav(active){return `<div class="bottom-nav">${['Home','Map','Create','Chats','Profile'].map(x=>`<div class="nav-item ${x===active?'active':''}">${x}</div>`).join('')}</div>`}function phoneBody(s){let out='';if(s.kind==='map')return mapVisual();if(s.hero==='event')out+=`<div class="event-hero">${s.badge?badge(s.badge,'blue'):''}</div>`;else if(s.hero)out+=`<div class="hero-art"></div>`;if(s.progress)out+=`<div class="progress"><span style="width:${s.progress}%"></span></div>`;if(s.kicker)out+=`<div class="eyebrow">${esc(s.kicker)}</div>`;if(s.h)out+=`<h1 class="hero-title">${esc(s.h)}</h1>`;if(s.p)out+=`<p class="body-copy">${esc(s.p)}</p>`;if(s.banner)out+=`<div class="banner ${s.banner[0]||''}">${esc(s.banner[1])}</div>`;if(s.search)out+=`<div class="searchbox">${esc(s.search)}</div>`;out+=chips(s.chips);out+=fields(s.fields);if(s.choices?.length)out+=`<div class="choice-grid">${s.choices.map((x,i)=>`<div class="choice ${i===0?'selected':''}">${esc(x)}</div>`).join('')}</div>`;out+=stats(s.stats);if(s.section)out+=`<div class="section-label"><span>${esc(s.section)}</span><a>See all</a></div>`;out+=cards(s.cards);out+=rows(s.rows);out+=messages(s.messages);if(s.illustration)out+=`<div class="illustration">${esc(s.illustration)}</div>`;out+=actions(s);return out}function phone(s){const top=s.top===false?'':`<div class="mobile-top"><div class="place">${esc(s.top||s.title)}</div><div class="icon-btn">•••</div></div>`;return `<div class="phone"><div class="statusbar"><span>9:41</span><span>5G · 92%</span></div><div class="phone-main"><div class="screen-content ${s.nav?'':'no-nav'}">${top}${phoneBody(s)}</div>${s.nav?nav(s.nav):''}</div></div>`}function deskTable(s){let head=(s.cols||['Name','Status','Details','Action']).map(x=>`<th>${esc(x)}</th>`).join('');let body=(s.table||[]).map(r=>`<tr>${r.map((x,i)=>`<td>${i===1&&String(x).includes('|')?String(x).split('|').map(y=>`<span class="role-chip">${esc(y)}</span>`).join(''):esc(x)}</td>`).join('')}</tr>`).join('');return `<div class="panel"><div class="panel-head"><h3>${esc(s.tableTitle||'Current')}</h3>${s.tableAction?`<span class="btn compact">${esc(s.tableAction)}</span>`:''}</div><table class="table"><thead><tr>${head}</tr></thead><tbody>${body}</tbody></table></div>`}function desktopBody(s){let out='';if(s.banner)out+=`<div class="banner ${s.banner[0]||''}">${esc(s.banner[1])}</div>`;if(s.stats?.length)out+=`<div class="desk-stats">${s.stats.map(x=>`<div class="desk-stat"><strong>${esc(x[1])}</strong><span>${esc(x[0])}</span></div>`).join('')}</div>`;if(s.kind==='analytics')out+=`<div class="panel"><div class="panel-head"><h3>${esc(s.chartTitle||'Participation')}</h3><span class="badge blue">Last 30 days</span></div><div class="chart">${[38,62,46,75,58,88,70,92,66,82,74,96].map(h=>`<div class="bar" style="height:${h}%"></div>`).join('')}</div></div>`;if(s.fields?.length||s.rows?.length){out+=`<div class="split"><div class="panel"><div class="panel-head"><h3>${esc(s.formTitle||'Details')}</h3></div>${fields(s.fields)}${actions(s)}</div><div>${rows(s.rows)}</div></div>`}else if(s.table?.length)out+=deskTable(s);if(s.panels?.length)out+=s.panels.map(x=>`<div class="panel ${x[2]||''}"><div class="panel-head"><h3>${esc(x[0])}</h3>${x[3]?`<span class="badge ${x[4]||''}">${esc(x[3])}</span>`:''}</div><p class="body-copy" style="margin:0">${esc(x[1])}</p></div>`).join('');return out}function side(active){let items=['Overview','Events','Recurring','Attendees','Check-in','Announcements','Analytics','Team','Settings'];return `<aside class="side"><div class="brand">Meet</div><div class="org-pill">Oodi Community<br><span style="color:#7f8ca2">Verified organization</span></div>${items.map(x=>`<div class="side-item ${x===active?'active':''}">${x}</div>`).join('')}</aside>`}function adminSide(active){let items=['Dashboard','Moderation','Reports','Appeals','Users','Events','Organizations','Verification','Ingestion','Dedupe','Operational flags','Client policy','Audit','Operations'];return `<aside class="side"><div class="brand">Meet Staff</div><div class="org-pill">Privileged console<br><span style="color:#7f8ca2">MFA · audited</span></div>${items.map(x=>`<div class="side-item ${x===active?'active':''}">${x}</div>`).join('')}</aside>`}function desktop(s){return `<div class="desktop-shell">${s.surface==='admin'?adminSide(s.nav||'Dashboard'):side(s.nav||'Overview')}<section class="desktop-main"><header class="desk-top"><div><div class="code-meta">${esc(s.route||'/')}</div><h2>${esc(s.h||s.title)}</h2></div>${s.primary?`<span class="btn compact">${esc(s.primary)}</span>`:''}</header><div class="desk-body">${s.p?`<p class="body-copy">${esc(s.p)}</p>`:''}${desktopBody(s)}</div></section></div>`}function card(s){let wrap=document.createElement('article');wrap.className=`spec-card ${s.surface==='consumer'?'':'desktop-card'}`;wrap.id=s.id;wrap.dataset.group=s.group;wrap.innerHTML=`<div class="spec-head"><div><div class="spec-id">${esc(s.id)} · ${esc(s.state||'REFERENCE')}</div><h3>${esc(s.title)}</h3><div class="spec-route">${esc(s.route||'')}</div></div><div class="spec-source">${esc(s.spec||'architecture')}</div></div>${s.surface==='consumer'?phone(s):desktop(s)}<div class="prototype-note">${esc(s.note||'Reference layout/hierarchy. Final implementation follows product, safety and state contracts.')}</div>`;return wrap}function mount(surface){let all=(window.MEET_SCREENS||[]).filter(s=>s.surface===surface),root=document.querySelector('#screens'),groups=[...new Set(all.map(s=>s.group))];groups.forEach(g=>{let sec=document.createElement('section');sec.className='group';sec.id=g.toLowerCase().replace(/[^a-z0-9]+/g,'-');let subset=all.filter(s=>s.group===g);sec.innerHTML=`<div class="group-title"><h2>${esc(g)}</h2><span>${subset.length} references</span></div><div class="screen-grid"></div>`;let grid=sec.querySelector('.screen-grid');subset.forEach(s=>grid.appendChild(card(s)));root.appendChild(sec)});document.querySelector('[data-count]')?.replaceChildren(document.createTextNode(String(all.length)))}window.MeetPrototype={mount};})();